    function __ESBMC_assume(bool) internal pure {}

    function run(uint depAmount, uint am, uint newMinSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmount)); require(depAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depAmount);
        c.SetMinSum(newMinSum); if (__ESBMC_reverted()) return;
        c.Deposit{value: depAmount}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        require(balBefore >= newMinSum);
        require(balBefore >= am);
        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        assert(!reverted && balAfter == balBefore - am);
    }

